report_styles:
@import "/assets/global/base.css";
 @font-face {
     font-family: 'Neuropol X';
     font-weight: 400;
     src: url('/assets/name/neuropol-x-rg.otf') 
}
/* Define variables */
 :root {
     --color-risk-critical: #6c1bad;
     --color-risk-high: #d33417;
     --color-risk-medium: #cc942c;
     --color-risk-low: #0096FF;
     --color-risk-info: #2e9e62;
}
/* Font */
 html {
     font-family: "Exo", sans-serif;
     font-size: 12pt;
     font-weight: 500;
}
/* Justification */
 p {
     text-align: justify;
     text-align-last: start;
}
/* Links */
 a {
     font-style: italic;
     text-decoration: none;
     color:inherit;
}
/* Code blocks */
 pre code {
     border: 1px solid black;
     font-family: "Source Code Pro";
     font-size: 8pt;
     font-weight: 600;
}
/* Table */
th {
     color: azure;
     background-color: #539466;
}
h1 {
  padding-bottom: 10px;
  border-bottom: solid 1px #96b3a6;
}

h2 {
  padding-top: 10px;
  padding-bottom: 10px;
}
/* Classes for risk colors */
 .risk-critical {
     color: var(--color-risk-critical) !important;
     font-weight: bold;
}
 .risk-high {
     color: var(--color-risk-high) !important;
     font-weight: bold;
}
 .risk-medium {
     color: var(--color-risk-medium) !important;
     font-weight: bold;
}
 .risk-low {
     color: var(--color-risk-low) !important;
     font-weight: bold;
}
 .risk-info {
     color: var(--color-risk-info) !important;
     font-weight: bold;
}
 .risk-bg-critical {
     background-color: var(--color-risk-critical) !important;
     color: white !important;
     white-space:nowrap;
}
 .risk-bg-high {
     background-color: var(--color-risk-high) !important;
     color: white !important;
     white-space:nowrap;
}
 .risk-bg-medium {
     background-color: var(--color-risk-medium) !important;
     color: white !important;
     white-space:nowrap;
}
 .risk-bg-low {
     background-color: var(--color-risk-low) !important;
     color: white !important;
     white-space:nowrap;
}
 .risk-bg-info {
     background-color: var(--color-risk-info) !important;
     color: white !important;
     white-space:nowrap;
}
/* Classes for retest status colors */
 .retest-status-open {
     background-color: var(--color-risk-high) !important;
     color: white !important;
}
 .retest-status-partial {
     background-color: var(--color-risk-medium) !important;
     color: white !important;
}
 .retest-status-resolved {
     background-color: var(--color-risk-info) !important;
     color: white !important;
}
/* Table styling */
 table, th, td {
     border: none;
     border-collapse: separate;

}
.nowrap {
  white-space: nowrap !important;
}
 tr {
     background-color: #d9f0e5;
     font-weight: 600;
     font-size: 10pt;
}
 tr:nth-child(even) {
     background-color: #7ca08e;
    /* Row alternate shading */
}
 tr.table-row-link td {
     padding: 0;
}
 tr.table-row-link td a {
     display: block;
     padding: 0.2em 0.5em 0.2em 0.5em;
     color: inherit;
     text-decoration: none;
     font-style: inherit;
}
 td.table-key {
     height: 3em;
     width: 10em;
     color: azure;
     background-color: #208547;
     font-weight: 600;
}
/* Tabela de findings */
 table.finding-header {
    /* border-collapse: separate;
     */
     border: none;
}
 .finding-header tr td {
     border: none;
}
 td.find-table-key {
     height: 2em;
     width: 10em;
     color: azure;
     background-color: #165e31;
}
 .finding-header th:first-child {
     font-family: Exo;
     border: none;
     border-top-left-radius: 12px;
     border-top-right-radius: 12px;
}

/* Fim da Tabela de findings */
/* Helper class for referencing page number */
 .ref-page::before {
     content: "" !important;
}
 .ref-page::after {
     content: target-counter(attr(href), page) !important;
}
 .ref-page .ref-title {
     display: none !important;
}
/* Styling affected_components list in findings */
 .finding-systems {
     padding-left: 1em;
}
 .finding-systems-cols {
     column-count: 2;
     padding-top: 1em;
     margin-bottom: 1em;
}
/* Footnotes */
 @page {
     @footnote {
         border-top: 1px solid black;
    }
}
 footnote {
     font-size: 8pt;
}
/* Watermark */
 #watermark {
     position: fixed;
     top: 8cm;
     left: 2cm;
     transform: rotate(-45deg);
     font-size: 100pt;
     opacity: 0.2;
}

/* #region toc */
 #toc li {
     /* font-size: 12pt !important; */
     list-style: none;
     margin: 0;
     padding: 0;
}
 #toc .ref::before {
     padding-right: 0.5em;
}
 #toc .ref::after {
     content: " " leader(".") " " target-counter(attr(href), page);
}
 #toc .toc-level1 {
     font-size: 1.2rem;
     font-weight: bold;
     margin-top: 0.8rem;
}
 #toc .toc-level2 {
     font-size: 1.1rem;
     font-weight: 500;
     margin-top: 0.5rem;
     margin-left: 2rem;
}
 #toc .toc-level3 {
     font-size: 1rem;
     font-weight: 400;
     margin-top: 0.4rem;
     margin-left: 4rem;
}
 #toc .toc-level4 {
     font-size: 1rem;
     font-weight: 400;
     margin-top: 0.4rem;
     margin-left: 4rem;
}
/* #endregion toc */
/* #region footer */
 #footer-left {
     font-family:'Gill Sans', 'Gill Sans MT', Calibri, 'Trebuchet MS', sans-serif;
     font-size: 10pt;
     position: running(footer-left);
}
 #footer-center {
     font-family:'Gill Sans', 'Gill Sans MT', Calibri, 'Trebuchet MS', sans-serif;
     font-size: 10pt;
     position: running(footer-center);
}
 @page {
     @bottom-left {
         content: element(footer-left);
    }
     @bottom-center {
         content: element(footer-center);
    }
     @bottom-right-corner {
         content: counter(page);
         font-size: 11pt;
    }
}
/* #endregion footer */
/* #region header */
 @page {
     margin: 30mm 20mm 25mm 20mm;
     @top-right {
         content: element(header-right);
         margin-bottom: 0mm;
         width: 50%;
    }
}
 #header-right {
     position: running(header-right);
     text-align: end;
}
 #header-right img {
     height: 15mm;
     width: auto;
}
/* #endregion header */
/* #region page-cover */
#page-cover .page-cover-title {
  position: absolute;
  top: 5mm;
  left: 0;
  width: 14cm;
}

#page-cover .page-cover-title h1 {
  font-size: 32pt;
  color: #000000;
  font-weight: 300;
}

#page-cover .page-cover-title h2 {
  font-size: 24pt;
  font-weight: 400;
  color: rgb(0, 0, 0);
}

#page-cover .page-cover-title h3 {
  font-size: 16pt;
  font-weight: 300;
  color: rgb(0, 0, 0);
}

#page-cover .page-cover-title h1, h2, h3 {
  margin: 0em;
}

@page :first {
  @top-right {
    content: none !important;
  }
  @bottom-left {
    content: none !important;
  }

  background: url('/assets/name/Capa-it4us.jpg');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  background-attachment: fixed;

  /* Hide footer*/
  @bottom-center {
    content: none !important;
  }
  @bottom-right-corner {
    content: none !important;
  }
}
/* #region page-backcover */
.page-backcover {
  page: page-backcover;
}
@page page-backcover {
  @top-right {
    content: none !important;
  }
  @bottom-left {
    content: none !important;
  }

  background: url('/assets/name/Capa-it4us.jpg');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  background-attachment: fixed;
  /* Hide footer*/
  @bottom-center {
    content: none !important;
  }
  @bottom-right-corner {
    content: none !important;
  }
}

.page-backcover-address {
  display: flex;
  font-size: 13pt;
  color: whitesmoke;
  position: absolute;
  top: 85%; 
  left: 50%;
  transform: translate(-50%, -50%);
  width: 140mm;
}

.page-backcover-url {
    font-size: 24pt;
    font-weight: bold;
    color: #E7353B;
    display:inline-block;
    padding: 25px 0;
    margin-right: 100px;
    border-top: 2px solid  #E7353B;
    border-bottom: 2px solid  #E7353B;
}

.page-backcover-center {
  display: flex; /* Add this to make the div a flex container */
  align-items: center; /* Add this to vertically center the logo and text */
  color: #E7353B;
  font-weight: 400;
  font-size: 26pt;
  position: absolute;
  top: 40%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 110mm;
}

.page-backcover-center img {
  margin-right: 20px; /* Add some space between the logo and the text */
}

/* #endregion page-backcover */
